{
  "probability": 0.89,
  "range_low": 0.82,
  "range_high": 0.95,
  "summary": [
    "Late-February polls show CDU ahead of Greens by about 1–5 percentage points, translating into CDU being the largest party in many seat-projection scenarios.",
    "Seat projections commonly place CDU around 36–37 seats versus Greens 28–35, supporting CDU as the largest party.",
    "Uncertainties remain from Greens momentum, AfD’s sizable share, and electoral-system nuances, but the posterior probability remains high at 89%."
  ],
  "confidence": "high",
  "narrative": "Anchored in Baden-Württemberg reference-class forecasts and updated with late-February polls and seat projections, the posterior that CDU wins the most seats is 89%. Despite Greens momentum and AfD fragmentation, a convergence of credible forecasts supports CDU as the largest party, though not guaranteed to have a majority.",
  "justification": {
    "anchor": {
      "probability": 0.60,
      "basis": "Baseline probability for CDU being the largest party in the BW reference class, reflecting historical tendencies (Greens often winning the most seats) and mid-2026 polling context; 0.60 provides a moderate starting point before updates."
    },
    "factor_updates": [
      {
        "factor": "CDU lead in late February 2026 polls",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Multiple credible polls around Feb 25–26 show CDU ahead (27–28%) vs Greens (22–27%), bolstering expectations of CDU being the largest-seat holder."
      },
      {
        "factor": "Greens momentum / closing gap",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Greens narrowing the gap in some surveys reduces certainty of CDU’s seat lead, introducing risk to the CDU-largest projection."
      },
      {
        "factor": "AfD vote share remains sizable",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "AfD around 18–20% fragments the vote and complicates which party ends with the most seats, especially in closer contests."
      },
      {
        "factor": "Seat projections place CDU as largest party",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Projected seat distributions commonly place CDU around mid-to-high 30s seats, ahead of Greens, supporting CDU as the largest party."
      },
      {
        "factor": "Historical baseline with Greens often winning more seats",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Historical precedents in BW (e.g., 2021 Greens as largest) temper CDU optimism and keep uncertainty high."
      }
    ],
    "synthesis_rationale": "The posterior 0.89 results from integrating a CDU lead signal from credible late-Feb polls with multiple seat-projection scenarios that favor CDU, tempered by Greens’ historical baseline and AfD fragmentation. We weighted near-term polls more heavily, adjusted for potential turnout and system changes, and applied calibration to reflect residual uncertainty; the final estimate reflects a conservative but high-confidence conclusion that CDU would be the largest party, not guaranteed to hold a majority."
  }
}

